def parse_json(json_str):
    """
    Parses a JSON string and returns the corresponding Python structure.
    """
    def parse_value(json_str):
        if json_str[0] == '{':
            return parse_object(json_str)
        elif json_str[0] == '[':
            return parse_array(json_str)
        elif json_str[0] == '"':
            return parse_string(json_str)
        elif json_str[0] in '0123456789-':
            return parse_number(json_str)
        elif json_str == 'true':
            return True
        elif json_str == 'false':
            return False
        elif json_str == 'null':
            return None
        else:
            raise ValueError('Invalid JSON')

    def parse_object(json_str):
        if json_str[0] != '{':
            raise ValueError('Invalid JSON')
        json_str = json_str[1:]
        obj = {}
        while json_str:
            key = parse_string(json_str)
            json_str = json_str[len(key) + 2:]
            if json_str[0] != ':':
                raise ValueError('Invalid JSON')
            json_str = json_str[1:]
            value = parse_value(json_str)
            json_str = json_str[len(str(value)) + 1:]
            obj[key] = value
        return obj

    def parse_array(json_str):
        if json_str[0] != '[':
            raise ValueError('Invalid JSON')
        json_str = json_str[1:]
        arr = []
        while json_str:
            if json_str[0] == ',':
                json_str = json_str[1:]
                continue
            elif json_str[0] == ']':
                json_str = json_str[1:]
                break
            value = parse_value(json_str)
            json_str = json_str[len(str(value)) + 1:]
            arr.append(value)
        return arr

    def parse_string(json_str):
        if json_str[0] != '"':
            raise ValueError('Invalid JSON')
        json_str = json_str[1:]
        string = ''
        while json_str:
            if json_str[0] == '"':
                json_str = json_str[1:]
                break
            elif json_str[0] == '\\':
                json_str = json_str[1:]
                if json_str[0] not in '"\\/bfnrt':
                    raise ValueError('Invalid JSON')
                string += json_str[0]
                json_str = json_str[1:]
            else:
                string += json_str[0]
                json_str = json_str[1:]
        return string

    def parse_number(json_str):
        if not json_str[0].isdigit() and json_str[0] != '-':
            raise ValueError('Invalid JSON')
        json_str = json_str[1:]
        number = 0
        while json_str:
            if json_str[0].isdigit():
                number = number * 10 + int(json_str[0])
                json_str = json_str[1:]
            elif json_str[0] == '.':
                json_str = json_str[1:]
                if not json_str[0].isdigit():
                    raise ValueError('Invalid JSON')
                number += float(json_str[0])
                json_str = json_str[1:]
            elif json_str[0] == 'e' or json_str[0] == 'E':
                json_str = json_str[1:]
                if json_str[0] not in '+-':
                    raise ValueError('Invalid JSON')
                json_str = json_str[1:]
                if not json_str[0].isdigit():
                    raise ValueError('Invalid JSON')
                number *= 10 ** int(json_str[0])
                json_str = json_str[1:]
            else:
                break
        return number

    return parse_value(json_str)

