def parse_json(json_str):
    json_str = json_str.strip()
    if not json_str.startswith('{') and not json_str.startswith('['):
        raise ValueError("Invalid JSON: JSON must start with '{' or '['")
    if not json_str.endswith('}') and not json_str.endswith(']'):
        raise ValueError("Invalid JSON: JSON must end with '}' or ']'")
    if json_str.count('{') != json_str.count('}'):
        raise ValueError("Invalid JSON: JSON must have matching '{' and '}'")
    if json_str.count('[') != json_str.count(']'):
        raise ValueError("Invalid JSON: JSON must have matching '[' and ']'")
    if '{"' in json_str and '}' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain nested '{' and '}'")
    if '[' in json_str and ']' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain nested '[' and ']'")
    if ',' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain ','")
    if ':' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain ':'")
    if 'true' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain 'true'")
    if 'false' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain 'false'")
    if 'null' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain 'null'")
    if ' ' in json_str:
        raise ValueError("Invalid JSON: JSON must not contain whitespace")
    if not json_str:
        raise ValueError("Invalid JSON: JSON must not be empty")
