import re

def parse_json(json_str):
    """
    Parses a JSON string and returns the corresponding Python structure.
    """
    def parse_value(value_str):
        """
        Parses a JSON value and returns the corresponding Python structure.
        """
        value_str = value_str.strip()
        if value_str.startswith('{'):
            return parse_object(value_str)
        elif value_str.startswith('['):
            return parse_array(value_str)
        elif value_str.startswith('"'):
            return parse_string(value_str)
        elif value_str.isdigit():
            return int(value_str)
        elif value_str.lower() in ['true', 'false']:
            return value_str.lower() == 'true'
        elif value_str == 'null':
            return None
        else:
            raise ValueError('Invalid JSON value')

    def parse_object(object_str):
        """
        Parses a JSON object and returns the corresponding Python dictionary.
        """
        object_str = object_str.strip()[1:-1]
        members = re.findall(r'(\w+):(.*?)(?:,|$)', object_str)
        return {member[0]: parse_value(member[1]) for member in members}

    def parse_array(array_str):
        """
